    std::uint64_t aWandererE = 0U; std::uint64_t aWandererF = 0U; std::uint64_t aWandererG = 0U; std::uint64_t aWandererH = 0U;
    std::uint64_t aWandererI = 0U; std::uint64_t aWandererJ = 0U; std::uint64_t aWandererK = 0U;

    aIngress = 0xF4B69A12BA853B04ULL;
    aCarry = 0x9560732DEFE8CD48ULL;
    aWandererA = 0xBE54A9BB54AC6C17ULL;
    aWandererB = 0x92DD21739A9704A0ULL;
    aWandererC = 0xEA01395345D9F304ULL;
    aWandererD = 0xE73F41AEB8C619D5ULL;
    aWandererE = 0xC31E5C29CA29F79DULL;
    aWandererF = 0xD685C2D1A8A34058ULL;
    aWandererG = 0xC33E3F0051AEA4A9ULL;
    aWandererH = 0x920667B59E421AFDULL;
    aWandererI = 0xC8F0601180B9C02FULL;
    aWandererJ = 0x9881A10B1B0BCE58ULL;
    aWandererK = 0xC42DEEB8BE3E544CULL;

    ////////////////////////////////////////////////////////
    //
    // Main twist loops
    //
    TwistExpander_Alnitak_Arx::TWIST_A(PARAMS_TWIST);

    TwistExpander_Alnitak_Arx::TWIST_B(PARAMS_TWIST);

    TwistExpander_Alnitak_Arx::TWIST_C(PARAMS_TWIST);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectB;

    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollB;

