    std::uint8_t *aFoldG = aFoldLaneB + (2U * W_KEY);
    std::uint8_t *aFoldH = aFoldLaneB + (3U * W_KEY);
    std::uint8_t *aFoldI = aFoldLaneC + (0U * W_KEY);
